#!/usr/bin/env node
/*
 * Copyright (c) 2026 Mindrian. BSL 1.1.
 *
 * tests/fixtures/272/generate-candidate.cjs
 *
 * Phase 272, PYPORT-05 (D-03 rank-agreement gate). CJS sibling of
 * tests/fixtures/272/generate-baseline.py. Runs the REAL lib/core/rs-engine.cjs
 * (plan 272-08) against tests/fixtures/272/room and writes the resulting
 * pairs to tests/fixtures/272/candidate-cjs.fixture.json in the same schema
 * as baseline-python.fixture.json.
 *
 * Parameters match generate-baseline.py's build_pairs EXACTLY -- topk=2000
 * (FULL_K, covers the whole 96-artifact fixture room; abs_diff_topk clamps
 * to n*(n-1)/2 anyway) and threshold=0.0 (generate-baseline.py's
 * build_pairs applies NO threshold filter at all; run_mode_internal's own
 * DEFAULT_THRESHOLD=0.30 would silently drop pairs the baseline kept,
 * invalidating the whole comparison -- see this plan's own instruction to
 * match generate-baseline.py's parameters exactly).
 *
 * This is a one-shot generator, not a test -- same convention as
 * generate-baseline.py and build-fixture-room.cjs. Run:
 *   node tests/fixtures/272/generate-candidate.cjs
 *
 * No em-dashes (CLAUDE.md HARD RULE). Use hyphens.
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const { runModeInternal } = require('../../../lib/core/rs-engine.cjs');

const ROOM_DIR = path.join(__dirname, 'room');
const CANDIDATE_PATH = path.join(__dirname, 'candidate-cjs.fixture.json');

const TOPK = 2000;
const THRESHOLD = 0.0;

async function main() {
  console.log(`generate-candidate: running runModeInternal against ${ROOM_DIR}`);
  const result = await runModeInternal(ROOM_DIR, { topk: TOPK, threshold: THRESHOLD });

  const payload = {
    schema_version: '1',
    phase: '272',
    purpose:
      'CJS rs-engine.cjs candidate output for the D-03 rank-agreement gate ' +
      '(PYPORT-05), generated by an ACTUAL runModeInternal(roomDir, opts) run ' +
      'against tests/fixtures/272/room -- not a stub. Compared against ' +
      'baseline-python.fixture.json by tests/272-rank-agreement.test.cjs.',
    source: 'tests/fixtures/272/room',
    generated_by: 'tests/fixtures/272/generate-candidate.cjs',
    embedding_model: result.metadata.embedding_model,
    topk: TOPK,
    threshold: THRESHOLD,
    artifact_count: result.metadata.artifact_count,
    edges_written: result.metadata.edges_written,
    pairs: result.pairs,
  };

  fs.writeFileSync(CANDIDATE_PATH, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  console.log(`generate-candidate: wrote ${result.pairs.length} pairs to ${CANDIDATE_PATH}`);
  console.log(`generate-candidate: embedding_model=${result.metadata.embedding_model}, edges_written=${result.metadata.edges_written}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
